@script trader npc
    setv tr_want 7
    setv tr_give 8
    name_var 0 tr_want
    name_var 1 tr_give
    jf trade_done after
    ask c3a.trade.ask
    jv 0 1 go
    say c3a.trade.no
    end
  go:
    trade flitter muncrit c3a.trade.nick tr_res
    jv tr_res 1 done
    jv tr_res 255 cancel
    say c3a.trade.wrong
    end
  cancel:
    say c3a.trade.no
    end
  done:
    setf trade_done
    say c3a.trade.done
    end
  after:
    name_var 0 tr_give
    say c3a.trade.after
@end
@script lady npc
    daycare_query dc_occ      # dc_occ, dc_sp, dc_lv + {v1} the fee, {v2} the levels gained
    name_var 0 dc_sp          # {v0} = the species in care
    say c3a.dc.hello
    jv dc_occ 1 occupied
    ask c3a.dc.ask_leave
    jv 0 1 leave
    say c3a.dc.no
    end
  leave:
    daycare_deposit dc_res
    jv dc_res 255 bye
    jv dc_res 0 last
    say c3a.dc.taken
    end
  last:
    say c3a.dc.last
    end
  bye:
    say c3a.dc.no
    end
  occupied:
    ask c3a.dc.report
    jv 0 1 take
    say c3a.dc.no
    end
  take:
    daycare_withdraw dc_res
    jv dc_res 1 gave
    jv dc_res 2 poor
    say c3a.dc.full
    end
  gave:
    say c3a.dc.back
    end
  poor:
    say c3a.dc.poor
@end
# native `calc` (rand / copyv / addvv): the host test starts it with script_start; it only writes vars (fuse_dir = 84, fuse_first = 0, fuse_second = 0, tr_want = 144)
@script calc_test interact
    setv dc_res 40
    setv tr_res 2
    copyv fuse_dir dc_res
    addvv fuse_dir tr_res
    addvv fuse_dir fuse_dir
    rand fuse_first 1
    rand fuse_second 0
    setv tr_want 200
    addvv tr_want tr_want
@end
# `music NAME` plays a track of assets/music/index.txt (the rival's theme while he walks up), `music_map` goes back to the map's own track. A real ambush follows the theme with
# `battle TRAINER VAR`: the battle starts its own music and the map's track returns after it by itself, so music_map is only needed when no battle follows.
@script ambush interact
    music rival
    wait 400
    say c3a.ambush
    music_map
@end
